const ASSET={first:'',glance:'',night:'',interview:'',note:'',link:'',video:'data:video/mp4;base64,'}
;

const ltVar=(n,f)=>(getComputedStyle(document.documentElement).getPropertyValue(n).trim()||f);
const colors={rose:ltVar('--lt-thread-rose','#ff659f'),violet:ltVar('--lt-thread-violet','#a86cff'),cyan:ltVar('--lt-thread-cyan','#69dcff'),amber:ltVar('--lt-thread-amber','#ffc96b'),pearl:'#e9dff3'}
;

// 기억 보드는 예시 판본과, 서버 기록을 쓰기 가능한 계정으로 연 경우에 편집할 수 있다.
// 공유 감상(share)은 읽기 전용이다. 서버 쓰기 가능 여부는 셸이 LT41.writable로 넘긴다.
function boardSaveEnabled(){try{return window.parent!==window&&window.parent.LT41?.source==='server'&&window.parent.LT41?.writable===true&&!LTDEMO.readOnly}catch{return false}}
const canEditBoard=LTDEMO.example||boardSaveEnabled();
let moments=LTDEMO.moments.map((m,i)=>{const pos=LT58Model.cardPosition(i);return{id:m.id,type:m.type==='memo'?'note':'photo',originalType:m.type==='memo'?'note':m.type,createdOrder:i+1,title:m.title,emotion:m.emotion,date:m.date,source:m.source||'예시 기록',mediaMetadata:m.mediaMetadata||null,memo:m.memo||m.whyNext||'',x:Number.isFinite(m.x)?m.x:pos.x,y:Number.isFinite(m.y)?m.y:pos.y,rot:Number.isFinite(m.rot)?m.rot:pos.rot,pinStyle:m.pinStyle,cardStyle:m.cardStyle,keywords:Array.isArray(m.keywords)?m.keywords:[],color:m.color||['rose','violet','cyan','amber'][i%4],asset:m.image,url:m.externalUrl||'',first:!!m.first}});

let connections=LTDEMO.edges.map((e,i)=>({id:'c'+i,kind:e.kind,a:e.from,b:e.to,why:e.kind==='related'?'관련 순간':e.reason||'부모·자식 연결',color:e.kind==='related'?'cyan':(canEditBoard?['rose','violet','cyan','amber'][Math.max(0,moments.findIndex(m=>m.id===e.from))%4]:'rose')}));

// 보드 저장(#372 후속): 바뀐 순간·연결을 셸에 넘겨 기존 워크스페이스 저장 경로(PUT /api/workspace)로 보낸다.
// 예시·공유는 보내지 않는다. 셸이 저장하지 못하면 토스트로 알린다.
function domainDateText(v){const s=String(v||'');if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;const m=s.match(/(\d{4})\.(\d{2})\.(\d{2})/);if(m)return `${m[1]}-${m[2]}-${m[3]}`;const d=new Date(s);return Number.isNaN(d.getTime())?new Date().toISOString().slice(0,10):d.toISOString().slice(0,10)}
function boardPayload(){const parentOf=id=>{const c=connections.find(c=>c.kind==='parent'&&c.b===id);return c?c.a:null};
const relatedOf=id=>[...new Set(connections.filter(c=>c.kind==='related'&&(c.a===id||c.b===id)).map(c=>c.a===id?c.b:c.a))];
return moments.map(m=>{const pc=connections.find(c=>c.kind==='parent'&&c.b===m.id);return{id:m.id,parentId:parentOf(m.id),relation:pc?(pc.why||''):'',links:relatedOf(m.id),title:m.title,note:m.memo||'',emotion:m.emotion||'설렘',date:domainDateText(m.date),url:m.url||'',...(m.mediaMetadata?{mediaMetadata:m.mediaMetadata}:{}),createdAt:m.createdAt||new Date().toISOString(),x:m.x,y:m.y,rot:m.rot,pinStyle:m.pinStyle,cardStyle:m.cardStyle,keywords:m.keywords||[],color:m.color}})}
function newBoardId(){let id;do{id='m'+Math.random().toString(36).slice(2,10)}while(moments.some(m=>m.id===id));return id}
function persistBoard(){if(!boardSaveEnabled())return;try{const treeId=window.parent.LT41.tree.id;window.parent.postMessage({type:'lt41-board-sync',treeId,moments:boardPayload()},location.origin)}catch{/* 셸이 없으면 저장하지 않는다 */}}
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type!=='lt41-board-saved')return;if(e.data.ok===false)toast(e.data.error||'서버에 저장하지 못했어요. 잠시 뒤 다시 시도해 주세요.')});

const replayPath=(()=>{const ids=[],seen=new Set();let m=LTDEMO.moments[0];while(m&&!seen.has(m.id)){ids.push(m.id);seen.add(m.id);m=LTDEMO.moments.find(x=>x.id===m.next)}return ids})();

let mobilePicker=null;

let view={x:0,y:0,z:.78}
,selected=LTDEMO.get(),drag=null,pan=null,connecting=null,pendingConn=null,undoStack=[],cinema=false,addType='photo',pinTap=null,selectedConn=null;

const $=s=>document.querySelector(s), cardLayer=$('#cardLayer'), threadLayer=$('#threadLayer'), world=$('#world'), viewport=$('#viewport');

const esc=LT58Model.escapeHTML;
function titleMode(){try{return window.parent?.LT41?.prefs?.titleDisplay||'both'}catch{return 'both'}}
function titleInfo(m){const v=window.LTTitle?.titleView?.(m,titleMode());return{main:v?.main||m?.title||'',sub:v?.sub||''}}
function titleMain(m){return titleInfo(m).main}
function titleSub(m){return titleInfo(m).sub}
function titleSubMarkup(m){const sub=titleSub(m);return sub?'<div class="videoTitle">▶ '+esc(sub)+'</div>':''}
function dateText(v){return window.LTTitle?.formatDisplayDate?.(v)||v||''}

function cardHTML(m){let media='';
if(m.url)media=LTMedia.markup(m.url,m.title,m.mediaMetadata,m.id);
else if(m.type==='note') media=`<div class="noteText">“${esc(m.memo)}”</div>`;
else if(m.type==='video') media=`<div class="media"><video muted playsinline loop poster="${m.asset}" src="${m.video}"></video><span class="playBadge">▶</span><span class="duration">${m.duration||'00:03'}</span></div>`;
else media=`<div class="media ${m.type==='link'||m.type==='youtube'?'linkMedia':''}"><img src="${m.asset}" alt=""><span class="${m.type==='youtube'?'playBadge':''}">${m.type==='youtube'?'▶':''}</span></div>`;
return `<article class="card ${m.first?'first':''} ${m.type==='note'?'noteCard':''}" data-id="${m.id}" style="left:${m.x}px;top:${m.y}px;--rot:${m.rot}deg;--pin:${colors[m.color]};--halo:${colors[m.color]}55">${m.first?'<div class="firstTag">첫 순간</div>':''}<button class="pin" data-pin="${m.id}" aria-hidden="true" tabindex="-1"></button>${media}<div class="cardBody"><div class="eyebrow"><span class="emotionDot"></span>${LTLabels.type(m.originalType||m.type)} 순간 · ${esc(m.emotion)}</div><h3>${esc(titleMain(m))}</h3>${titleSubMarkup(m)}<div class="meta"><span>${esc(dateText(m.date))}</span><span>${m.type==='link'||m.type==='youtube'?'↗':''}</span></div>${m.type!=='note'?`<div class="memo">${esc(m.memo)}</div>`:''}${m.url?`<div class="domain">${esc(m.source)}</div>`:''}</div></article>`}

function renderCards(){cardLayer.innerHTML=moments.map(cardHTML).join('');
cardLayer.querySelectorAll('.card').forEach(el=>bindCard(el));
if(selected)selectMoment(selected,false)}

function pinPoint(id){const m=moments.find(x=>x.id===id);
const card=cardLayer.querySelector(`[data-id="${id}"]`);
let w=card?.offsetWidth||242;
return {x:m.x+w/2,y:m.y-13}}

function pathD(c){const a=pinPoint(c.a),b=pinPoint(c.b);return LT58Model.threadPath(a,b).d}

function renderThreads(){threadLayer.innerHTML=connections.map(c=>{let col=colors[c.color];return `<g class="threadGroup" data-cid="${c.id}"><path class="threadGlow" d="${pathD(c)}" stroke="${col}"/><path class="threadColor" d="${pathD(c)}" stroke="${col}"/><path class="threadCore" d="${pathD(c)}"/><path class="threadHit" d="${pathD(c)}"/></g>`}).join('');
threadLayer.querySelectorAll('.threadGroup').forEach(g=>g.addEventListener('pointerdown',e=>{e.stopPropagation();showWhy(g.dataset.cid)}))}

function rerenderThreads(){threadLayer.querySelectorAll('.threadGroup').forEach(g=>{let c=connections.find(x=>x.id===g.dataset.cid);g.querySelectorAll('path').forEach(p=>p.setAttribute('d',pathD(c)))})}

function applyView(animated=false){world.style.transition=animated?'transform 1s cubic-bezier(.22,.8,.2,1)':'none';
world.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.z})`;
$('#zoomLabel').textContent=Math.round(view.z*100)+'%'}

function fitAll(animated=true){let vw=viewport.clientWidth,vh=viewport.clientHeight;
let z=LT58Model.fitZoom(vw,vh);
view.z=z;
view.x=(vw-2400*z)/2;
view.y=(vh-2200*z)/2;
applyView(animated)}

function screenToWorld(cx,cy){let r=viewport.getBoundingClientRect();
return{x:(cx-r.left-view.x)/view.z,y:(cy-r.top-view.y)/view.z}}

function snapshot(){undoStack.push(JSON.stringify({moments:moments.map(m=>({...m})),connections:connections.map(c=>({...c}))}));
if(undoStack.length>24)undoStack.shift()}

function undo(){let s=undoStack.pop();
if(!s)return toast('되돌릴 작업이 없어요.');
let o=JSON.parse(s);
moments=o.moments;
connections=o.connections;
renderCards();
renderThreads();
persistBoard();
toast('이전 상태로 돌아왔어요.')}

function bindCard(el){let id=el.dataset.id;
el.addEventListener('pointerdown',e=>{if(e.target.classList.contains('pin'))return;if(cinema)return;e.stopPropagation();snapshot();let m=moments.find(x=>x.id===id),p=screenToWorld(e.clientX,e.clientY);drag={id,dx:p.x-m.x,dy:p.y-m.y};el.setPointerCapture?.(e.pointerId);selectMoment(id,true)});
el.addEventListener('pointermove',e=>{if(!drag||drag.id!==id)return;let p=screenToWorld(e.clientX,e.clientY),m=moments.find(x=>x.id===id);m.x=Math.max(70,Math.min(1320,p.x-drag.dx));m.y=Math.max(120,Math.min(760,p.y-drag.dy));el.style.left=m.x+'px';el.style.top=m.y+'px';rerenderThreads()});
el.addEventListener('pointerup',e=>{if(drag?.id===id){let m=moments.find(x=>x.id===id);for(const o of moments){if(o.id===id)continue;if(Math.abs(o.x-m.x)<165&&Math.abs(o.y-m.y)<165){m.x+=34;m.y+=28;el.style.left=m.x+'px';el.style.top=m.y+'px';rerenderThreads();break}}drag=null;el.releasePointerCapture?.(e.pointerId)}});
let pin=el.querySelector('.pin');
pin.addEventListener('pointerdown',e=>startConnect(e,id));
pin.addEventListener('pointerup',e=>endPinTap(e,id));
el.addEventListener('mouseenter',()=>{let v=el.querySelector('video:not(.lt-user-video)');if(v&&!cinema)v.play().catch(()=>{})});
el.addEventListener('mouseleave',()=>{let v=el.querySelector('video:not(.lt-user-video)');if(v&&!el.classList.contains('cinemaFocus')){v.pause();v.currentTime=0}})}

function selectMoment(id,open=true){selected=id;
mobilePicker?.select(id);
document.querySelectorAll('.card').forEach(c=>c.classList.toggle('selected',c.dataset.id===id));
if(open){let m=moments.find(x=>x.id===id);
const _ti=titleInfo(m);$('#dTitle').textContent=_ti.main;const _ds=$('#detailSub');if(_ds){_ds.textContent=_ti.sub?'▶ '+_ti.sub:'';_ds.hidden=!_ti.sub}
$('#dBasic').innerHTML=`${esc(dateText(m.date))}<br><b>${esc(m.emotion)}</b> · ${esc(m.source)}${m.memo&&!connections.some(c=>c.a===id&&c.why===m.memo)?`<br><br>${esc(m.memo)}`:""}`;
let outs=connections.filter(c=>c.kind==='parent'&&c.a===id),ins=connections.filter(c=>c.kind==='parent'&&c.b===id);
$('#dConn').innerHTML=outs.length?outs.map(c=>`→ ${esc(titleMain(moments.find(x=>x.id===c.b)))}<br><span style="color:#bca9c5">${esc(c.why)}</span>`).join('<br><br>'):`${ins.length}개의 이전 연결 · 아직 다음 순간 없음`;
$('#detail').classList.add('open')}}

function startConnect(e,id){if(cinema)return;
e.stopPropagation();
let isTouch=e.pointerType==='touch';
if(isTouch){if(pinTap&&pinTap!==id){completeConnection(pinTap,id);
pinTap=null;
document.querySelectorAll('.pin').forEach(p=>p.classList.remove('connecting'));
return}pinTap=id;
e.currentTarget.classList.add('connecting');
toast('연결할 다음 Memory Pin을 탭하세요.');
return}connecting={from:id,pointer:e.pointerId};
e.currentTarget.classList.add('connecting');
let p=pinPoint(id);
$('#draftThread').setAttribute('d',`M ${p.x} ${p.y} L ${p.x} ${p.y}`);
$('#draftThread').setAttribute('opacity','1');
e.currentTarget.setPointerCapture?.(e.pointerId)}

window.addEventListener('pointermove',e=>{if(!connecting)return;let a=pinPoint(connecting.from),b=screenToWorld(e.clientX,e.clientY);$('#draftThread').setAttribute('d',`M ${a.x} ${a.y} C ${a.x+(b.x-a.x)*.3} ${Math.max(a.y,b.y)+70}, ${a.x+(b.x-a.x)*.7} ${Math.max(a.y,b.y)+70}, ${b.x} ${b.y}`)});

window.addEventListener('pointerup',e=>{if(!connecting)return;let target=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.pin');let from=connecting.from;document.querySelectorAll('.pin').forEach(p=>p.classList.remove('connecting'));connecting=null;$('#draftThread').setAttribute('opacity','0');if(target&&target.dataset.pin!==from)completeConnection(from,target.dataset.pin)});

function endPinTap(e,id){}

function wouldCycle(a,b){let cur=a,seen=new Set();while(cur){if(cur===b)return true;if(seen.has(cur))break;seen.add(cur);const c=connections.find(x=>x.kind==='parent'&&x.b===cur);cur=c?c.a:null}return false}
function completeConnection(a,b){if(a===b)return toast('같은 순간끼리는 연결하지 않아요.');
if(connections.some(c=>c.a===a&&c.b===b))return toast('이미 존재하는 Connection이에요.');
if(wouldCycle(a,b))return toast('이 연결은 순간들이 원을 이뤄 저장할 수 없어요.');
snapshot();
// 한 순간의 이전 순간은 하나만 저장된다(도메인 계약). 새로 이으면 기존 부모 연결을 바꾼다.
connections=connections.filter(c=>!(c.kind==='parent'&&c.b===b&&c.a!==a));
pendingConn={a,b};
$('#whyModal').classList.add('open')}

function showWhy(cid){selectedConn=cid;
let c=connections.find(x=>x.id===cid),a=moments.find(x=>x.id===c.a),b=moments.find(x=>x.id===c.b);
$('#whyBubble').innerHTML=`<b>${esc(titleMain(a))} → ${esc(titleMain(b))}</b><br>${esc(c.why)}${canEditBoard?' <button id="deleteConnBubble">연결 지우기</button>':''}`;
$('#whyBubble').classList.add('show');
setTimeout(()=>{let b=$('#deleteConnBubble');if(b)b.onclick=deleteSelectedConnection},0);
clearTimeout(showWhy.t);
showWhy.t=setTimeout(()=>$('#whyBubble').classList.remove('show'),5200)}

function deleteSelectedConnection(){const guard=LT58Model.editGuard(canEditBoard);if(guard.blocked){toast(guard.message);
return}if(!selectedConn)return;
snapshot();
const gone=connections.find(c=>c.id===selectedConn);
if(gone?.kind==='parent'&&!connections.some(c=>c.id!==gone.id&&c.kind==='parent'&&c.b===gone.b)){toast('시작 순간은 하나여야 해요. 이 연결은 지울 수 없어요.');return}
connections=LT58Model.removeConnection(connections,selectedConn);
selectedConn=null;
persistBoard();
renderThreads();
$('#whyBubble').classList.remove('show');
toast('Connection을 지웠어요. 되돌리기로 되돌릴 수 있어요.')}

function animateNewThread(cid){let g=threadLayer.querySelector(`[data-cid="${cid}"]`);
if(!g)return;
let p=g.querySelector('.threadColor'),core=g.querySelector('.threadCore'),len=p.getTotalLength();
[p,core].forEach(x=>{x.style.strokeDasharray=len;x.style.strokeDashoffset=len;x.style.transition='stroke-dashoffset .9s cubic-bezier(.2,.75,.2,1)';requestAnimationFrame(()=>x.style.strokeDashoffset='0')});
setTimeout(()=>[p,core].forEach(x=>{x.style.strokeDasharray='';x.style.strokeDashoffset='';x.style.transition=''}),1000)}

function toast(t){let el=$('#toast');
el.textContent=t;
el.classList.add('show');
clearTimeout(toast.t);
toast.t=setTimeout(()=>el.classList.remove('show'),2200)}

function addMoment(m,connectFrom=null){snapshot();
moments.push(m);
renderCards();
renderThreads();
let el=cardLayer.querySelector(`[data-id="${m.id}"]`);
el.classList.add('landing');
el.querySelector('.pin').classList.add('pinImpact');
setTimeout(()=>{el.classList.remove('landing');el.querySelector('.pin').classList.remove('pinImpact')},1000);
selectMoment(m.id,true);
toast('순간이 꽂혔어요.');
if(connectFrom){pendingConn={a:connectFrom,b:m.id};
setTimeout(()=>$('#whyModal').classList.add('open'),950)}}

function formFor(type){let a=$('#formArea');
if(type==='photo')a.innerHTML='<input class="field" id="mediaFile" type="file" accept="image/*"><div style="font-size:10px;color:#9b89a5;margin-top:6px">로컬 이미지는 브라우저 안에서만 미리 봅니다.</div>';
else if(type==='video')a.innerHTML='<input class="field" id="mediaFile" type="file" accept="video/*"><div style="font-size:10px;color:#9b89a5;margin-top:6px">선택/hover 시 muted preview.</div>';
else if(type==='link'||type==='youtube')a.innerHTML='<input class="field" id="urlField" placeholder="https://..." value="https://lovetree.example/memory"><div style="font-size:10px;color:#9b89a5;margin-top:6px">Prototype metadata parser · 실제 crawler 아님.</div>';
else a.innerHTML='<textarea class="field" id="noteField" rows="3" placeholder="남기고 싶은 문장">좋아하게 된 이유를 잊고 싶지 않았어요.</textarea>'}

function openAdd(){formFor(addType);
$('#addModal').classList.add('open')}

function confirmAdd(){let id=newBoardId(),type=addType,title=$('#momentTitle').value||'새로운 순간',emotion=$('#momentEmotion').value||'설렘',memo=$('#momentMemo').value||'',asset=ASSET.note,video=null,url=null;
let file=$('#mediaFile')?.files?.[0];
if((type==='photo'||type==='video')&&file){asset=URL.createObjectURL(file);
if(type==='video')video=asset}else if(type==='photo')asset=ASSET.glance;
else if(type==='video'){asset=ASSET.first;
video=ASSET.video}else if(type==='link'||type==='youtube'){asset=ASSET.link;
url=$('#urlField')?.value||'https://lovetree.example'}let n={id,type,title,emotion,date:new Date().toISOString().slice(0,10),source:type==='photo'?'Local image':type==='video'?'Local video':type==='note'?'마음 한마디':'Prototype link metadata',memo,x:620+(moments.length%3)*120,y:360+(moments.length%2)*100,rot:[-4,3,-2,4,2][moments.length%5],color:['rose','violet','cyan','amber'][moments.length%4],asset,video,url,duration:'00:03'};
if(type==='note')n.memo=$('#noteField')?.value||memo;
$('#addModal').classList.remove('open');
addMoment(n,selected)}

function openViewer(id){let m=moments.find(x=>x.id===id);
if(!m)return;
const _vi=titleInfo(m);$('#vTitle').textContent=_vi.main;
let box=$('#viewerMedia');
if(m.url)box.innerHTML=LTMedia.markup(m.url,m.title,m.mediaMetadata,m.id);
else if(m.type==='video')box.innerHTML=`<video src="${m.video}" poster="${m.asset}" controls autoplay muted playsinline style="width:100%;max-height:420px;object-fit:contain"></video>`;
else if(m.type==='note')box.innerHTML=`<div style="padding:40px;color:#f7edf8;font-size:22px;line-height:1.6">“${esc(m.memo)}”</div>`;
else box.innerHTML=`<img src="${m.asset}" style="width:100%;max-height:420px;object-fit:cover">`;
$('#vMeta').innerHTML=(_vi.sub?'<div class="videoTitle">▶ '+esc(_vi.sub)+'</div>':'')+`${esc(LTLabels.type(m.originalType||m.type))} · ${esc(dateText(m.date))} · ${esc(m.emotion)}<br>출처: ${esc(m.source)}${m.url?`<br>URL: ${esc(m.url)}`:''}<br>마음 한마디: ${esc(m.memo)}`;
$('#viewerModal').classList.add('open')}

function focusMoment(id,caption){let m=moments.find(x=>x.id===id),el=cardLayer.querySelector(`[data-id="${id}"]`),cx=m.x+el.offsetWidth/2,cy=m.y+el.offsetHeight/2;
let vw=viewport.clientWidth,vh=viewport.clientHeight;
view.z=Math.min(vw<700?1.05:1.22,1.25);
view.x=vw/2-cx*view.z;
view.y=vh/2-cy*view.z;
applyView(true);
document.querySelectorAll('.card').forEach(c=>{c.classList.toggle('cinemaFocus',c.dataset.id===id);c.classList.toggle('cinemaDim',c.dataset.id!==id)});
let v=el.querySelector('video:not(.lt-user-video)');
if(v){v.currentTime=0;
v.play().catch(()=>{})}if(caption){$('#cinemaCaption').textContent=caption;
$('#cinemaCaption').classList.add('show')}}

function sleep(ms){return new Promise(r=>setTimeout(r,ms))}

function animateHotTip(path,dur=1900){return new Promise(resolve=>{let tip=$('#hotTip'),len=path.getTotalLength(),st=performance.now();tip.setAttribute('opacity','1');function f(now){let t=Math.min(1,(now-st)/dur),pt=path.getPointAtLength(len*t);tip.setAttribute('cx',pt.x);tip.setAttribute('cy',pt.y);tip.setAttribute('r',String(4+2*Math.sin(t*Math.PI)));if(t<1)requestAnimationFrame(f);else{tip.setAttribute('opacity','0');resolve()}}requestAnimationFrame(f)})}

async function travelConnection(a,b){let c=connections.find(x=>x.a===a&&x.b===b);
if(!c)return;
let g=threadLayer.querySelector(`[data-cid="${c.id}"]`),path=g.querySelector('.threadColor'),len=path.getTotalLength();
path.style.strokeDasharray=len;
path.style.strokeDashoffset=len;
path.style.transition='none';
path.getBoundingClientRect();
path.style.transition='stroke-dashoffset 1.7s cubic-bezier(.3,.7,.2,1)';
path.style.strokeDashoffset='0';
g.querySelector('.threadGlow').style.opacity='.75';
$('#cinemaCaption').textContent=c.why;
$('#cinemaCaption').classList.add('show');
await animateHotTip(path,1700);
g.querySelector('.threadGlow').style.opacity='.25';
path.style.strokeDasharray='';
path.style.strokeDashoffset='';
path.style.transition='';
}

async function startCinema(fromIndex=0){if(cinema)return;
cinema=true;
$('#detail').classList.remove('open');
$('#cinemaOverlay').classList.add('active');
$('#cinemaTitle').classList.add('show');
$('#finalCTA').classList.remove('show');
document.body.classList.remove('boardBloom');
headerFade(true);
await sleep(900);
for(let i=fromIndex;i<replayPath.length;i++){let id=replayPath[i],m=moments.find(x=>x.id===id);
focusMoment(id,`${m.emotion} · ${titleMain(m)}`);
await sleep(i===0?1500:1100);
if(id==='m3'){let alt=connections.find(x=>x.a==='m3'&&x.b==='m7');
let ag=alt&&threadLayer.querySelector(`[data-cid="${alt.id}"]`);
if(ag){ag.querySelector('.threadGlow').style.opacity='.9';
$('#cinemaCaption').textContent='여기서 다른 경로도 열렸어요.';
await sleep(550);
ag.querySelector('.threadGlow').style.opacity='.25'}}if(i<replayPath.length-1){await travelConnection(id,replayPath[i+1]);
await sleep(450)}}$('#cinemaCaption').classList.remove('show');
document.querySelectorAll('.card').forEach(c=>{c.classList.remove('cinemaDim','cinemaFocus')});
fitAll(true);
await sleep(900);
document.body.classList.add('boardBloom');
threadLayer.querySelectorAll('.threadGlow').forEach(p=>p.style.opacity='.85');
await sleep(450);
$('#finalCTA').classList.add('show')}

function endCinema(){cinema=false;
$('#cinemaOverlay').classList.remove('active');
$('#cinemaTitle').classList.remove('show');
$('#cinemaCaption').classList.remove('show');
$('#finalCTA').classList.remove('show');
document.body.classList.remove('boardBloom');
threadLayer.querySelectorAll('.threadGlow').forEach(p=>p.style.opacity='');
document.querySelectorAll('.card video').forEach(v=>{v.pause();v.currentTime=0});
document.querySelectorAll('.card').forEach(c=>c.classList.remove('cinemaDim','cinemaFocus'));
headerFade(false);
fitAll(true)}

function headerFade(on){document.querySelector('header').style.opacity=on?'.18':'1';
document.querySelector('.toolbar').style.opacity=on?'0':'1';
$('#cinemaBtn').style.opacity=on?'0':'1'}

let boardTouches=new Map(),pinch=null;
viewport.addEventListener('pointerdown',e=>{if(cinema||e.target.closest('.card'))return;if(e.pointerType==='touch'){boardTouches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(boardTouches.size===1){pan={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y}}else if(boardTouches.size===2){let a=[...boardTouches.values()],dx=a[1].x-a[0].x,dy=a[1].y-a[0].y;pinch={dist:Math.hypot(dx,dy),z:view.z,x:view.x,y:view.y,cx:(a[0].x+a[1].x)/2,cy:(a[0].y+a[1].y)/2};pan=null}return}pan={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};viewport.setPointerCapture?.(e.pointerId)});
viewport.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&boardTouches.has(e.pointerId)){boardTouches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(boardTouches.size===2&&pinch){let a=[...boardTouches.values()],d=Math.hypot(a[1].x-a[0].x,a[1].y-a[0].y),nz=Math.max(.38,Math.min(1.45,pinch.z*d/pinch.dist)),r=viewport.getBoundingClientRect(),wx=(pinch.cx-r.left-pinch.x)/pinch.z,wy=(pinch.cy-r.top-pinch.y)/pinch.z;view.z=nz;view.x=pinch.cx-r.left-wx*nz;view.y=pinch.cy-r.top-wy*nz;applyView(false)}else if(pan){view.x=pan.vx+(e.clientX-pan.x);view.y=pan.vy+(e.clientY-pan.y);applyView(false)}return}if(!pan)return;view.x=pan.vx+(e.clientX-pan.x);view.y=pan.vy+(e.clientY-pan.y);applyView(false)});
function endBoardPointer(e){if(e.pointerType==='touch'){boardTouches.delete(e.pointerId);
if(boardTouches.size<2)pinch=null;
if(boardTouches.size===0)pan=null;
return}pan=null}
viewport.addEventListener('pointerup',endBoardPointer);
viewport.addEventListener('pointercancel',endBoardPointer);
viewport.addEventListener('wheel',e=>{if(cinema)return;e.preventDefault();let before=screenToWorld(e.clientX,e.clientY),factor=Math.exp(-e.deltaY*.0012),nz=Math.max(.38,Math.min(1.45,view.z*factor));let r=viewport.getBoundingClientRect();view.z=nz;view.x=e.clientX-r.left-before.x*nz;view.y=e.clientY-r.top-before.y*nz;applyView(false)},{passive:false});

